import React, { useState, useEffect, useMemo, useRef } from "react";
import { useNavigate } from "react-router-dom";
import api from "../../api/axiosConfig";
import { jsPDF } from "jspdf";
import autoTable from 'jspdf-autotable';
import {
    BsBox, BsSearch, BsGraphUp,
    BsBell,
    BsFilter, BsEye, BsPencil, BsTrash, BsExclamationTriangle,
    BsClockHistory, BsFileText
} from 'react-icons/bs';
import {
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, ResponsiveContainer,
    PieChart, Pie, Cell, Legend,
    AreaChart, Area // <--- Add these two
} from "recharts";

// A placeholder Base64 string for a "Box/Nexus" logo (Black & White)
// You can replace this string with your own using a site like https://www.base64-image.de/
const LOGO_BASE64 = "data:image/png;base64,";

const IMAGE_BASE_URL = "http://localhost:8081/user/uploads";
const DEFAULT_IMG = "https://via.placeholder.com/400x300?text=NO+ASSET+IMAGE";

function DisplayItem() {
    const navigate = useNavigate();

    // 1. GET THE ROLE
    const userRole = localStorage.getItem('userRole'); // 'ADMIN' or 'USER'
    const isAdmin = userRole === 'ADMIN';

    // --- STATE ---
    const [inventoryItems, setInventoryItems] = useState([]);
    const [loading, setLoading] = useState(true);
    const [viewMode, setViewMode] = useState('dashboard'); // 'dashboard', 'grid', 'list'
    const [searchQuery, setSearchQuery] = useState("");
    const [selectedItem, setSelectedItem] = useState(null); // For Dossier Modal
    const [showNotifications, setShowNotifications] = useState(false);
    const [showFilterModal, setShowFilterModal] = useState(false);
    const [selectedCategories, setSelectedCategories] = useState([]);
    const [stockFilter, setStockFilter] = useState('all'); // 'all', 'low', 'ok'

    // NEW STATES FOR HISTORY
    const [historyLogs, setHistoryLogs] = useState([]);
    const [activeTab, setActiveTab] = useState('details'); // 'details' or 'history'

    // NEW STATE FOR TRANSITION ANIMATION
    const [isNavigating, setIsNavigating] = useState(false);

    // --- TRANSITION HANDLER (THE ANIMATION LOGIC) ---
    const handleTransition = (target) => {
        setIsNavigating(true); // 1. Start Animation

        // 2. Wait 1 second
        setTimeout(() => {
            if (typeof target === 'string') {
                navigate(target); // If text, go to that URL (Back Button)
            } else if (typeof target === 'function') {
                target(); // If function, run it (Pagination)
                setIsNavigating(false); // Stop animation since we aren't leaving the page
            }
        }, 1000);
    };

    // Pagination
    const [currentPage, setCurrentPage] = useState(1);
    const itemsPerPage = 8;

    const notifRef = useRef();

    // --- INITIAL LOAD ---
    useEffect(() => {
        loadInventory();
    }, []);

    const loadInventory = async () => {
        setLoading(true);
        try {
            const result = await api.get("/inventory");
            setInventoryItems(result.data);
        } catch (error) {
            console.error("Error loading inventory:", error);
            // Show error to user
            alert("Failed to load inventory data. Please try again later.");
        } finally {
            setLoading(false);
        }
    }

    // Fetch History when an item is selected
    useEffect(() => {
        if (selectedItem) {
            setActiveTab('details'); // Reset to details tab
            api.get(`/history/${selectedItem.id}`)
                .then(res => setHistoryLogs(res.data))
                .catch(err => console.error("Error fetching history", err));
        }
    }, [selectedItem]);

    // --- NOTIFICATIONS SYSTEM ---
    const lowStockItems = inventoryItems.filter(i => parseInt(i.itemQty) < 100);
    const notificationCount = lowStockItems.length;

    // --- ANALYTICS DATA CALCULATION ---
    const stats = useMemo(() => {
        const totalItems = inventoryItems.length;
        const totalStock = inventoryItems.reduce((acc, item) => acc + parseInt(item.itemQty || 0), 0);
        const criticalStock = inventoryItems.filter(i => parseInt(i.itemQty) < 10).length;

        // Data for Pie Chart (Category Distribution)
        const categoryMap = inventoryItems.reduce((acc, item) => {
            acc[item.itemCategory] = (acc[item.itemCategory] || 0) + 1;
            return acc;
        }, {});
        const categoryData = Object.keys(categoryMap).map(key => ({ name: key, value: categoryMap[key] }));

        // Data for Bar Chart (Top Stocked Items)
        const stockLevelData = [...inventoryItems]
            .sort((a, b) => parseInt(b.itemQty) - parseInt(a.itemQty))
            .slice(0, 5)
            .map(item => ({ name: item.itemName.substring(0, 10), qty: parseInt(item.itemQty) }));

        // --- NEW: Mock Trend Data (6 Months) ---
        // In a real app, this would come from an API history endpoint.
        // We'll generate a smooth curve based on current stock.
        const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun"];
        const trendData = months.map((month, index) => {
            // Create a pseudo-random fluctuation around the average stock
            const fluctuation = Math.sin(index) * 20;
            const avgStock = totalStock > 0 ? (totalStock / (totalItems || 1)) : 50;

            return {
                name: month,
                stock: Math.floor(avgStock + fluctuation + (index * 5)), // Slight upward trend
                inbound: Math.floor(avgStock * 0.4 + fluctuation),
                outbound: Math.floor(avgStock * 0.3 + (index * 2))
            };
        });

        return { totalItems, totalStock, criticalStock, categoryData, stockLevelData, trendData }; // <--- Return trendData
    }, [inventoryItems]);

    // --- UNIQUE CATEGORIES FOR FILTER ---
    const uniqueCategories = useMemo(() => {
        return [...new Set(inventoryItems.map(item => item.itemCategory))];
    }, [inventoryItems]);

    // --- ACTIONS ---
    const deleteItem = async (id) => {
        if (window.confirm("/// SYSTEM WARNING ///\nThis action will permanently delete the asset record.")) {
            try {
                await api.delete(`/inventory/${id}`);
                loadInventory();
            } catch (error) {
                alert("Deletion failed.");
            }
        }
    };

    const generatePDF = () => {
        const doc = new jsPDF();
        const pageWidth = doc.internal.pageSize.width;
        const pageHeight = doc.internal.pageSize.height;

        // --- THEME CONFIG ---
        const colors = {
            black: '#000000',
            darkGrey: '#2c2c2c',
            lightGrey: '#e5e5e5',
            white: '#ffffff'
        };

        // --- 1. PREMIUM HEADER (The "Two Pager" Look) ---
        // Draw massive black header block
        doc.setFillColor(colors.black);
        doc.rect(0, 0, pageWidth, 75, 'F');

        // Logo (Centered in the black block)
        const logoSize = 18;
        const logoX = (pageWidth - logoSize) / 2;
        // Assuming LOGO_BASE64 is defined globally as before
        try {
            doc.addImage(LOGO_BASE64, 'PNG', logoX, 10, logoSize, logoSize);
        } catch (e) {
            console.warn("Logo error", e);
        }

        // Title "LOGISTICS CORP" (White, Serif, Centered)
        doc.setFont("times", "roman");
        doc.setFontSize(32);
        doc.setTextColor(colors.white);
        doc.text("LOGISTICS CORP", pageWidth / 2, 45, { align: "center" });

        // Subtitle (White with spacing)
        doc.setFont("helvetica", "bold");
        doc.setFontSize(9);
        doc.setTextColor(200, 200, 200);

        const dateStr = new Date().toLocaleDateString().toUpperCase();
        const subtitleText = `INVENTORY MASTER REPORT  |  ${dateStr}`;

        // --- MANUAL CENTERING FIX ---
        // 1. Get width of text normally
        const textWidth = doc.getTextWidth(subtitleText);

        // 2. Add extra width for charSpace (approx 2 points per character)
        const charSpacingTotal = (subtitleText.length - 1) * 2;
        const totalWidth = textWidth + (charSpacingTotal * 0.3527); // Convert pt to mm approx

        // 3. Calculate Start X: (PageWidth - TotalWidth) / 2
        const startX = (pageWidth - totalWidth) / 2;

        doc.text(subtitleText, startX, 55, { charSpace: 2 });

        // --- 2. OVERVIEW SECTION ---
        let finalY = 90;
        doc.setFont("times", "bold");
        doc.setFontSize(16);
        doc.setTextColor(colors.black);
        doc.text("Executive Overview", 14, finalY);

        doc.setFont("helvetica", "normal");
        doc.setFontSize(10);
        doc.setTextColor(80, 80, 80);
        doc.text("This document serves as the official registry of all warehouse assets. The data below highlights critical stock levels and total asset valuation.", 14, finalY + 8, { maxWidth: 180 });

        // --- 3. SUMMARY GRID (The "Boxed" Look) ---
        // Calculate Stats
        const totalItems = inventoryItems.length;
        const globalStock = inventoryItems.reduce((acc, item) => acc + parseInt(item.itemQty || 0), 0);
        const criticalCount = inventoryItems.filter(item => parseInt(item.itemQty) < 10).length;
        const topCategory = stats.categoryData.length > 0
            ? stats.categoryData.sort((a, b) => b.value - a.value)[0].name
            : "N/A";

        autoTable(doc, {
            startY: finalY + 20,
            theme: 'grid', // Use grid to get the borders
            head: [['TOTAL ASSETS', 'GLOBAL VOLUME', 'CRITICAL ALERTS', 'TOP CATEGORY']],
            body: [[
                totalItems.toString(),
                globalStock.toString(),
                criticalCount.toString(),
                topCategory.toUpperCase()
            ]],
            styles: {
                font: 'helvetica',
                fontSize: 11,
                halign: 'center',
                cellPadding: 10,
                lineColor: [0, 0, 0], // Black borders
                lineWidth: 0.1,
                textColor: colors.black
            },
            headStyles: {
                fillColor: [255, 255, 255], // White background for headers
                textColor: [100, 100, 100], // Grey text for headers
                fontStyle: 'bold',
                fontSize: 8,
                halign: 'center',
                lineColor: [0, 0, 0],
                lineWidth: 0.1
            },
            bodyStyles: {
                fillColor: [255, 255, 255], // White background for body
                fontStyle: 'bold',
                fontSize: 14 // Large numbers
            }
        });

        // --- 4. INVENTORY TABLE (The "Detailed" Look) ---
        doc.setFont("times", "bold");
        doc.setFontSize(16);
        doc.setTextColor(colors.black);
        doc.text("Detailed Inventory Data", 14, doc.lastAutoTable.finalY + 20);

        const tableRows = inventoryItems.map(item => {
            const qty = parseInt(item.itemQty);
            const status = qty < 10 ? "CRITICAL" : (qty < 50 ? "LOW" : "GOOD");
            return [
                item.itemId,
                item.itemName,
                item.itemCategory,
                item.itemQty,
                status,
                // Truncate details if too long to prevent layout breaking
                (item.itemDetails || "-").substring(0, 50) + (item.itemDetails?.length > 50 ? "..." : "")
            ];
        });

        autoTable(doc, {
            startY: doc.lastAutoTable.finalY + 25,
            head: [['ID', 'ASSET NAME', 'CATEGORY', 'QTY', 'STATUS', 'NOTES']],
            body: tableRows,
            theme: 'plain',
            styles: {
                fontSize: 9,
                cellPadding: 6,
                textColor: colors.darkGrey,
                valign: 'middle'
            },
            headStyles: {
                fillColor: [0, 0, 0], // Solid Black Header
                textColor: [255, 255, 255], // White Text
                fontStyle: 'bold',
                halign: 'left',
                textTransform: 'uppercase'
            },
            columnStyles: {
                0: { cellWidth: 25, font: 'courier' }, // ID Monospace
                1: { cellWidth: 40, fontStyle: 'bold' }, // Name Bold
                2: { cellWidth: 30 },
                3: { cellWidth: 20, halign: 'center' },
                4: { cellWidth: 25, fontStyle: 'bold' },
                5: { cellWidth: 'auto' } // Notes take remaining space
            },
            alternateRowStyles: {
                fillColor: [245, 245, 245] // Very light grey stripes for readability
            },
            didParseCell: function (data) {
                // Color code the Status column
                if (data.section === 'body' && data.column.index === 4) {
                    if (data.cell.raw === 'CRITICAL') {
                        data.cell.styles.textColor = [220, 53, 69]; // Red
                    } else if (data.cell.raw === 'LOW') {
                        data.cell.styles.textColor = [255, 193, 7]; // Orange/Gold
                    } else {
                        data.cell.styles.textColor = [25, 135, 84]; // Green
                    }
                }
            }
        });

        // --- 5. FOOTER (Black Bar at Bottom) ---
        const pageCount = doc.internal.getNumberOfPages();
        for (let i = 1; i <= pageCount; i++) {
            doc.setPage(i);

            // Footer Background
            doc.setFillColor(0, 0, 0);
            doc.rect(0, pageHeight - 15, pageWidth, 15, 'F');

            // Footer Text
            doc.setFont("helvetica", "normal");
            doc.setFontSize(8);
            doc.setTextColor(255, 255, 255);

            doc.text('LOGISTICS CORP INTERNAL DOCUMENT', 14, pageHeight - 9);
            doc.text(`PAGE ${i} OF ${pageCount}`, pageWidth - 14, pageHeight - 9, { align: 'right' });
        }

        doc.save("Logistics_Corp_Inventory.pdf");
    };

    // --- FILTERING ---
    const filteredItems = inventoryItems.filter(item => {
        const matchesSearch = searchQuery === "" ||
            item.itemName.toLowerCase().includes(searchQuery.toLowerCase()) ||
            item.itemId.toLowerCase().includes(searchQuery.toLowerCase());

        const matchesCategory = selectedCategories.length === 0 || selectedCategories.includes(item.itemCategory);

        const matchesStock = stockFilter === 'all' ||
            (stockFilter === 'low' && parseInt(item.itemQty) < 10) ||
            (stockFilter === 'ok' && parseInt(item.itemQty) >= 10);

        return matchesSearch && matchesCategory && matchesStock;
    });

    const indexOfLastItem = currentPage * itemsPerPage;
    const indexOfFirstItem = indexOfLastItem - itemsPerPage;
    const currentItems = filteredItems.slice(indexOfFirstItem, indexOfLastItem);
    const totalPages = Math.ceil(filteredItems.length / itemsPerPage);

    // --- STYLES (MONOCHROME PREMIUM) ---
    const styles = {
        wrapper: {
            backgroundColor: '#f8f9fa',
            minHeight: '100vh',
            fontFamily: "'Inter', sans-serif",
            color: '#000',
            overflowX: 'hidden'
        },
        heroSection: {
            background: 'linear-gradient(135deg, #ffffff 0%, #f4f4f5 100%)',
            padding: '3rem 2rem',
            borderBottom: '1px solid #e5e5e5',
            position: 'relative'
        },
        statCard: {
            background: '#fff',
            border: '1px solid #e5e5e5',
            padding: '1.5rem',
            height: '100%',
            transition: 'transform 0.2s',
            boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.05)'
        },
        actionBtn: {
            background: '#000',
            color: '#fff',
            border: 'none',
            padding: '10px 25px',
            borderRadius: '0',
            fontWeight: '600',
            letterSpacing: '1px',
            textTransform: 'uppercase',
            fontSize: '0.8rem',
            display: 'flex',
            alignItems: 'center',
            gap: '8px',
            transition: 'all 0.3s'
        },
        secondaryBtn: {
            background: '#fff',
            color: '#000',
            border: '1px solid #000',
            padding: '10px 25px',
            borderRadius: '0',
            fontWeight: '600',
            letterSpacing: '1px',
            textTransform: 'uppercase',
            fontSize: '0.8rem',
            display: 'flex',
            alignItems: 'center',
            gap: '8px'
        },
        navPill: (isActive) => ({
            cursor: 'pointer',
            padding: '10px 20px',
            borderBottom: isActive ? '3px solid #000' : '3px solid transparent',
            color: isActive ? '#000' : '#888',
            fontWeight: '600',
            transition: 'all 0.2s'
        }),
        chartCard: {
            background: '#fff',
            border: '1px solid #e5e5e5',
            padding: '20px',
            height: '100%',
            boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.05)'
        },
        itemCard: {
            background: '#fff',
            border: 'none',
            transition: 'transform 0.2s, box-shadow 0.2s',
            height: '100%',
            boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.05)'
        },
        badge: (type) => ({
            background: type === 'low' ? '#fff' : '#000',
            color: type === 'low' ? '#000' : '#fff',
            border: type === 'low' ? '1px solid #000' : 'none',
            padding: '4px 8px',
            fontSize: '0.7rem',
            fontWeight: 'bold',
            letterSpacing: '0.5px'
        }),
        // Modal Styles
        modalOverlay: {
            position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
            backgroundColor: 'rgba(0,0,0,0.85)', zIndex: 9999,
            display: 'flex', justifyContent: 'center', alignItems: 'center',
            backdropFilter: 'blur(5px)'
        },
        modalContent: {
            background: '#fff', width: '90%', maxWidth: '900px',
            maxHeight: '90vh', overflowY: 'auto',
            position: 'relative', display: 'flex', flexDirection: 'column'
        },
        backButton: {
            background: 'none',
            border: 'none',
            color: '#6c757d',
            textTransform: 'uppercase',
            fontSize: '1rem',
            fontWeight: 'bold',
            letterSpacing: '1px',
            padding: '10px 20px',
            //marginBottom: '2rem',
            //marginTop: '0.6rem',
            // padding: 0,
            cursor: 'pointer'
        },

        // NEW: Loader Overlay Styles (Frosted Glass)
        loaderOverlay: {
            position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
            backgroundColor: 'rgba(255, 255, 255, 0.8)', // White with opacity
            backdropFilter: 'blur(8px)', // The "Frosted" effect
            zIndex: 10000,
            display: 'flex', justifyContent: 'center', alignItems: 'center', flexDirection: 'column'
        }
    };

    // --- CHART COLORS (MONOCHROME) ---
    const COLORS = ['#000000', '#333333', '#666666', '#999999', '#cccccc'];

    if (loading) return <div className="d-flex justify-content-center align-items-center vh-100 bg-white"><div className="spinner-grow text-dark"></div></div>;

    return (
        <div style={styles.wrapper}>

            {/* CSS Animation Injection for the Bouncing Dots */}
            <style>{`
                .wave-loader {
                    display: flex;
                    justify-content: center;
                    align-items: center;
                }
                .wave-dot {
                    width: 15px;
                    height: 15px;
                    margin: 0 5px;
                    background-color: #000; /* Black dots */
                    border-radius: 50%;
                    animation: wave 1.2s infinite ease-in-out both;
                }
                .wave-dot:nth-child(1) { animation-delay: -1.1s; }
                .wave-dot:nth-child(2) { animation-delay: -1.0s; }
                .wave-dot:nth-child(3) { animation-delay: -0.9s; }
                .wave-dot:nth-child(4) { animation-delay: -0.8s; }
                .wave-dot:nth-child(5) { animation-delay: -0.7s; }
                
                @keyframes wave {
                    0%, 80%, 100% { transform: scale(0); }
                    40% { transform: scale(1); }
                }
            `}</style>

            {/* --- 1. HERO SECTION --- */}
            <header style={styles.heroSection}>
                <div className="container-fluid">

                    {/* Top Row: Brand & Notifications */}
                    <div className="d-flex justify-content-between align-items-start mb-5">
                        <div className="d-flex align-items-center">
                            <div style={{ width: '60px', height: '60px', background: '#000', color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.8rem', marginRight: '20px' }}>
                                <BsBox />
                            </div>
                            <div>
                                <h1 className="display-6 fw-bold mb-0" style={{ letterSpacing: '-1px' }}>INVENTORY NEXUS</h1>
                                <p className="text-muted small mb-0 text-uppercase" style={{ letterSpacing: '2px' }}>System V2.0 // Logistics Corp MS</p>
                            </div>
                        </div>

                        {/* Notification Bell */}
                        <div className="position-relative" ref={notifRef}>
                            <button
                                onClick={() => setShowNotifications(!showNotifications)}
                                style={{ background: 'white', border: '1px solid #e5e5e5', width: '50px', height: '50px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.2rem', cursor: 'pointer' }}
                            >
                                <BsBell />
                                {notificationCount > 0 && <span className="position-absolute top-0 end-0 translate-middle badge rounded-pill bg-black">{notificationCount}</span>}
                            </button>

                            {/* Notification Dropdown */}
                            {showNotifications && (
                                <div style={{ position: 'absolute', right: 0, top: '60px', width: '350px', background: '#fff', border: '1px solid #000', boxShadow: '0 20px 50px rgba(0,0,0,0.2)', zIndex: 100 }}>
                                    <div className="p-3 border-bottom bg-light"><h6 className="mb-0 fw-bold">SYSTEM ALERTS</h6></div>
                                    <div style={{ maxHeight: '300px', overflowY: 'auto' }}>
                                        {lowStockItems.length === 0 ? (
                                            <div className="p-4 text-center text-muted small">No active alerts.</div>
                                        ) : (
                                            lowStockItems.map(item => (
                                                <div key={item.id} className="p-3 border-bottom d-flex align-items-start hover-bg-light">
                                                    <BsExclamationTriangle className="text-dark me-3 mt-1" />
                                                    <div>
                                                        <div className="fw-bold small">{item.itemName}</div>
                                                        <div className="text-muted" style={{ fontSize: '0.75rem' }}>Low Stock: Only {item.itemQty} units remaining.</div>
                                                    </div>
                                                </div>
                                            ))
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Quick Stats Row */}
                    <div className="row g-4">
                        <div className="col-lg-3 col-md-6">
                            <div style={styles.statCard}>
                                <div className="d-flex justify-content-between">
                                    <div>
                                        <div className="text-uppercase small fw-bold text-muted mb-2">Total Assets</div>
                                        <div className="display-6 fw-bold">{stats.totalItems}</div>
                                    </div>
                                    <BsBox size={24} className="text-muted opacity-35" />
                                </div>
                            </div>
                        </div>
                        <div className="col-lg-3 col-md-6">
                            <div style={styles.statCard}>
                                <div className="d-flex justify-content-between">
                                    <div>
                                        <div className="text-uppercase small fw-bold text-muted mb-2">Global Stock</div>
                                        <div className="display-6 fw-bold">{stats.totalStock}</div>
                                    </div>
                                    <BsGraphUp size={24} className="text-muted opacity-35" />
                                </div>
                            </div>
                        </div>
                        <div className="col-lg-3 col-md-6">
                            <div style={styles.statCard}>
                                <div className="d-flex justify-content-between">
                                    <div>
                                        <div className="text-uppercase small fw-bold text-muted mb-2">Critical Alerts</div>
                                        <div className="display-6 fw-bold text-danger" style={{ color: stats.criticalStock > 0 ? '#000' : '#ccc' }}>{stats.criticalStock}</div>
                                    </div>
                                    <BsExclamationTriangle size={24} className={stats.criticalStock > 0 ? "text-dark" : "text-muted opacity-35"} />
                                </div>
                            </div>
                        </div>
                        <div className="col-lg-3 col-md-6">
                            <div style={styles.statCard} className="d-flex flex-column justify-content-center align-items-start gap-2 bg-black text-white">
                                {isAdmin && (
                                    <button className="btn btn-link text-white text-decoration-none p-0 fw-bold" onClick={() => handleTransition('/add-item')}>
                                        + ADD NEW ITEM
                                    </button>
                                )}
                                <div style={{ width: '100%', height: '1px', background: 'rgba(255,255,255,0.2)' }}></div>
                                {isAdmin && (
                                    <button
                                        className="btn btn-link text-white text-decoration-none p-0 fw-bold"
                                        onClick={() => handleTransition(generatePDF)}
                                    >
                                        ↓ EXPORT REPORT
                                    </button>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </header>

            {/* --- 2. CONTROL BAR --- */}
            <div className="container-fluid px-4 py-4 sticky-top bg-white border-bottom" style={{ zIndex: 90 }}>
                <div className="row align-items-center g-3">
                    {/* View Switcher */}
                    <div className="col-md-4">
                        <div className="d-flex gap-4">
                            <div>
                                <button style={styles.backButton} onClick={() => handleTransition('/')}>← Back</button>
                            </div>
                            <div onClick={() => setViewMode('dashboard')} style={styles.navPill(viewMode === 'dashboard')}>DASHBOARD</div>
                            <div onClick={() => setViewMode('grid')} style={styles.navPill(viewMode === 'grid')}>GRID</div>
                            <div onClick={() => setViewMode('list')} style={styles.navPill(viewMode === 'list')}>LIST</div>
                        </div>
                    </div>
                    {/* Search */}
                    <div className="col-md-8">
                        <div className="input-group">
                            <span className="input-group-text bg-white border-end-0 rounded-0"><BsSearch /></span>
                            <input
                                type="text"
                                className="form-control border-start-0 rounded-0 shadow-none"
                                placeholder="Search by ID, Name or Category..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                            />
                            <button className="btn btn-outline-dark rounded-0 px-4" onClick={() => setShowFilterModal(true)}><BsFilter /> FILTER</button>
                        </div>
                    </div>
                </div>
            </div>

            {/* --- 3. MAIN CONTENT AREA --- */}
            <div className="container-fluid px-4 py-5">

                {/* VIEW: DASHBOARD (ANALYTICS) */}
                {viewMode === 'dashboard' && (
                    <>
                        {/* Row 1: Existing Bar & Pie Charts */}
                        <div className="row g-4 mb-4"> {/* Added mb-4 for spacing */}
                            <div className="col-lg-8">
                                <div style={styles.chartCard}>
                                    <h6 className="fw-bold mb-4 text-uppercase">Stock Levels by Top Items</h6>
                                    <ResponsiveContainer width="100%" height={300}>
                                        <BarChart data={stats.stockLevelData}>
                                            <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                                            <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                                            <YAxis />
                                            <RechartsTooltip cursor={{ fill: '#f5f5f5' }} contentStyle={{ border: '1px solid #000' }} />
                                            <Bar dataKey="qty" fill="#000" barSize={40} />
                                        </BarChart>
                                    </ResponsiveContainer>
                                </div>
                            </div>
                            <div className="col-lg-4">
                                <div style={styles.chartCard}>
                                    <h6 className="fw-bold mb-4 text-uppercase">Category Distribution</h6>
                                    <ResponsiveContainer width="100%" height={300}>
                                        <PieChart>
                                            <Pie data={stats.categoryData} cx="50%" cy="50%" outerRadius={80} fill="#8884d8" dataKey="value">
                                                {stats.categoryData.map((entry, index) => (
                                                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                                ))}
                                            </Pie>
                                            <RechartsTooltip contentStyle={{ border: '1px solid #000' }} />
                                            <Legend />
                                        </PieChart>
                                    </ResponsiveContainer>
                                </div>
                            </div>
                        </div>

                        {/* --- NEW: Row 2 - Stock Trends Area Chart --- */}
                        <div className="row g-4">
                            <div className="col-12">
                                <div style={styles.chartCard}>
                                    <div className="d-flex justify-content-between align-items-center mb-4">
                                        <h6 className="fw-bold m-0 text-uppercase">Inventory Movement Trends (6 Month)</h6>
                                        <div className="small text-muted">Live Analysis</div>
                                    </div>

                                    <ResponsiveContainer width="100%" height={250}>
                                        <AreaChart data={stats.trendData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                                            <defs>
                                                {/* Gradient for a premium fill effect */}
                                                <linearGradient id="colorStock" x1="0" y1="0" x2="0" y2="1">
                                                    <stop offset="5%" stopColor="#000000" stopOpacity={0.1} />
                                                    <stop offset="95%" stopColor="#000000" stopOpacity={0} />
                                                </linearGradient>
                                            </defs>
                                            <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: '#888', fontSize: 12 }} />
                                            <YAxis axisLine={false} tickLine={false} tick={{ fill: '#888', fontSize: 12 }} />
                                            <CartesianGrid vertical={false} stroke="#f0f0f0" />
                                            <RechartsTooltip contentStyle={{ border: '1px solid #000', borderRadius: '0px' }} />

                                            {/* The Area Lines */}
                                            <Area
                                                type="monotone"
                                                dataKey="stock"
                                                stroke="#000"
                                                strokeWidth={2}
                                                fillOpacity={1}
                                                fill="url(#colorStock)"
                                            />
                                            <Area
                                                type="monotone"
                                                dataKey="inbound"
                                                stroke="#666"
                                                strokeWidth={2}
                                                strokeDasharray="5 5" // Dashed line for secondary metric
                                                fill="none"
                                            />
                                        </AreaChart>
                                    </ResponsiveContainer>
                                </div>
                            </div>
                        </div>
                    </>
                )}

                {/* VIEW: GRID */}
                {viewMode === 'grid' && (
                    <div className="row g-4">
                        {currentItems.map(item => (
                            <div className="col-lg-3 col-md-6" key={item.id}>
                                <div style={styles.itemCard} className="d-flex flex-column h-100">
                                    <div style={{ position: 'relative', height: '200px', overflow: 'hidden', background: '#f0f0f0' }}>
                                        <img
                                            src={item.itemImage ? `${IMAGE_BASE_URL}/${item.itemImage}` : DEFAULT_IMG}
                                            style={{ width: '100%', height: '100%', objectFit: 'cover', filter: 'grayscale(100%)', transition: 'filter 0.3s' }}
                                            onMouseOver={(e) => e.target.style.filter = 'grayscale(0%)'}
                                            onMouseOut={(e) => e.target.style.filter = 'grayscale(100%)'}
                                            alt={item.itemName}
                                        />
                                        <div style={{ position: 'absolute', top: 10, right: 10 }}>
                                            <span style={styles.badge(parseInt(item.itemQty) < 10 ? 'low' : 'ok')}>
                                                {parseInt(item.itemQty) < 10 ? 'LOW STOCK' : 'IN STOCK'}
                                            </span>
                                        </div>
                                    </div>
                                    <div className="p-4 flex-grow-1 d-flex flex-column">
                                        <div className="text-muted small mb-1">{item.itemCategory}</div>
                                        <h5 className="fw-bold mb-1">{item.itemName}</h5>
                                        <div className="small text-muted mb-3">ID: {item.itemId}</div>

                                        <div className="mt-auto pt-3 border-top d-flex justify-content-between align-items-center">
                                            <div className="fw-bold fs-5">{item.itemQty} <span className="small fw-normal text-muted">units</span></div>
                                            <button className="btn btn-sm btn-dark rounded-0" onClick={() => setSelectedItem(item)}>VIEW</button>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                )}

                {/* VIEW: LIST */}
                {viewMode === 'list' && (
                    <div className="bg-white border">
                        <table className="table table-hover mb-0">
                            <thead className="bg-light">
                                <tr>
                                    <th className="py-3 ps-4">ASSET</th>
                                    <th className="py-3">CATEGORY</th>
                                    <th className="py-3">STOCK LEVEL</th>
                                    <th className="py-3">STATUS</th>
                                    <th className="py-3 text-end pe-4">ACTIONS</th>
                                </tr>
                            </thead>
                            <tbody>
                                {currentItems.map(item => (
                                    <tr key={item.id} className="align-middle">
                                        <td className="ps-4">
                                            <div className="d-flex align-items-center">
                                                <img
                                                    src={item.itemImage ? `${IMAGE_BASE_URL}/${item.itemImage}` : DEFAULT_IMG}
                                                    style={{ width: '40px', height: '40px', objectFit: 'cover', filter: 'grayscale(100%)', marginRight: '15px' }}
                                                    alt=""
                                                />
                                                <div>
                                                    <div className="fw-bold">{item.itemName}</div>
                                                    <div className="small text-muted">{item.itemId}</div>
                                                </div>
                                            </div>
                                        </td>
                                        <td>{item.itemCategory}</td>
                                        <td><span className="fw-bold">{item.itemQty}</span> units</td>
                                        <td>
                                            <span style={styles.badge(parseInt(item.itemQty) < 10 ? 'low' : 'ok')}>
                                                {parseInt(item.itemQty) < 10 ? 'ALERT' : 'OK'}
                                            </span>
                                        </td>
                                        <td className="text-end pe-4">
                                            <button className="btn btn-link text-dark p-0 me-3" onClick={() => setSelectedItem(item)}><BsEye /></button>
                                            {isAdmin && (
                                                <>
                                                    <button className="btn btn-link text-dark p-0 me-3" onClick={() => handleTransition(`/update-item/${item.id}`)}><BsPencil /></button>
                                                    <button className="btn btn-link text-danger p-0" onClick={() => deleteItem(item.id)}><BsTrash /></button>
                                                </>
                                            )}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}

                {/* --- PAGINATION --- */}
                {viewMode !== 'dashboard' && (
                    <div className="d-flex justify-content-between align-items-center mt-4">
                        <div className="text-muted small">Showing page {currentPage} of {totalPages}</div>
                        <div className="btn-group">
                            <button className="btn btn-outline-dark rounded-0 btn-sm" disabled={currentPage === 1} onClick={() => handleTransition(() => setCurrentPage(p => p - 1))}>PREV</button>
                            <button className="btn btn-outline-dark rounded-0 btn-sm" disabled={currentPage === totalPages} onClick={() => handleTransition(() => setCurrentPage(p => p + 1))}>NEXT</button>
                        </div>
                    </div>
                )}
            </div>

            {/* --- 4. DOSSIER MODAL WITH TABS --- */}
            {selectedItem && (
                <div style={styles.modalOverlay} onClick={() => setSelectedItem(null)}>
                    <div style={styles.modalContent} onClick={e => e.stopPropagation()}>

                        {/* Header */}
                        <div className="d-flex justify-content-between align-items-center p-4 bg-black text-white">
                            <div>
                                <div className="small opacity-50 mb-1">ASSET DOSSIER</div>
                                <h3 className="m-0 fw-bold">{selectedItem.itemName}</h3>
                            </div>
                            <div className="text-end">
                                <div className="small opacity-50">SYSTEM ID</div>
                                <div className="fw-bold font-monospace">{selectedItem.itemId}</div>
                            </div>
                        </div>

                        {/* Navigation Tabs (New) */}
                        <div className="d-flex border-bottom bg-light">
                            <button
                                onClick={() => setActiveTab('details')}
                                className="btn rounded-0 py-3 px-4 fw-bold small"
                                style={{
                                    borderBottom: activeTab === 'details' ? '3px solid #000' : '3px solid transparent',
                                    background: activeTab === 'details' ? '#fff' : 'transparent',
                                    color: activeTab === 'details' ? '#000' : '#888'
                                }}
                            >
                                <BsFileText className="me-2" /> SPECIFICATIONS
                            </button>
                            <button
                                onClick={() => setActiveTab('history')}
                                className="btn rounded-0 py-3 px-4 fw-bold small"
                                style={{
                                    borderBottom: activeTab === 'history' ? '3px solid #000' : '3px solid transparent',
                                    background: activeTab === 'history' ? '#fff' : 'transparent',
                                    color: activeTab === 'history' ? '#000' : '#888'
                                }}
                            >
                                <BsClockHistory className="me-2" /> AUDIT LOG
                            </button>
                        </div>

                        {/* Modal Body Content */}
                        <div className="d-flex flex-column flex-grow-1" style={{ minHeight: '400px' }}>

                            {/* TAB 1: DETAILS (Your Existing Layout) */}
                            {activeTab === 'details' && (
                                <div className="d-flex flex-column flex-md-row flex-grow-1 animate-fade-in">
                                    <div className="col-md-5 bg-light d-flex align-items-center justify-content-center p-4 border-end">
                                        <img
                                            src={selectedItem.itemImage ? `${IMAGE_BASE_URL}/${selectedItem.itemImage}` : DEFAULT_IMG}
                                            style={{ maxWidth: '100%', maxHeight: '300px', objectFit: 'contain' /*filter:'grayscale(100%)'*/, boxShadow: '0 10px 30px rgba(0,0,0,0.1)' }}
                                            alt="Asset"
                                        />
                                    </div>
                                    <div className="col-md-7 p-5">
                                        <div className="mb-4">
                                            <label className="text-muted small fw-bold text-uppercase d-block mb-1">Category</label>
                                            <span className="fs-5">{selectedItem.itemCategory}</span>
                                        </div>
                                        <div className="row mb-4">
                                            <div className="col-6">
                                                <label className="text-muted small fw-bold text-uppercase d-block mb-1">Current Stock</label>
                                                <span className="fs-4 fw-bold">{selectedItem.itemQty}</span>
                                            </div>
                                            <div className="col-6">
                                                <label className="text-muted small fw-bold text-uppercase d-block mb-1">Status</label>
                                                <span style={styles.badge(parseInt(selectedItem.itemQty) < 10 ? 'low' : 'ok')}>
                                                    {parseInt(selectedItem.itemQty) < 10 ? 'LOW STOCK' : 'OPTIMAL'}
                                                </span>
                                            </div>
                                        </div>
                                        <div className="mb-5">
                                            <label className="text-muted small fw-bold text-uppercase d-block mb-1">Technical Specifications</label>
                                            <p className="text-muted" style={{ lineHeight: '1.6' }}>{selectedItem.itemDetails || "No additional details available for this asset."}</p>
                                        </div>

                                        <div className="d-grid gap-2 d-md-flex mt-auto">
                                            {isAdmin && (
                                                <>
                                                    <button className="btn btn-dark rounded-0 px-4" onClick={() => handleTransition(`/update-item/${selectedItem.id}`)}>EDIT RECORD</button>
                                                    <button className="btn btn-outline-danger rounded-0 px-4" onClick={() => { deleteItem(selectedItem.id); setSelectedItem(null); }}>DELETE</button>
                                                </>
                                            )}
                                            <button className="btn btn-outline-dark rounded-0 px-4 ms-auto" onClick={() => setSelectedItem(null)}>CLOSE</button>
                                        </div>
                                    </div>
                                </div>
                            )}

                            {/* TAB 2: HISTORY/AUDIT LOG */}
                            {activeTab === 'history' && (
                                <div className="p-4 animate-fade-in">
                                    <div className="mb-4">
                                        <h5 className="fw-bold mb-3">Activity Timeline</h5>
                                        {historyLogs.length === 0 ? (
                                            <div className="text-center py-5 text-muted">
                                                <BsClockHistory size={30} className="mb-2" />
                                                <p className="mb-0">No audit records found for this asset.</p>
                                            </div>
                                        ) : (
                                            <div className="timeline">
                                                {historyLogs.map((log, index) => (
                                                    <div key={index} className="d-flex mb-4">
                                                        <div className="flex-shrink-0 me-3">
                                                            <div className="bg-dark rounded-circle d-flex align-items-center justify-content-center" style={{ width: '30px', height: '30px' }}>
                                                                <span className="text-white" style={{ fontSize: '0.6rem' }}>{index + 1}</span>
                                                            </div>
                                                        </div>
                                                        <div className="flex-grow-1 border-bottom pb-3">
                                                            <div className="d-flex justify-content-between">
                                                                <h6 className="mb-1">{log.action.replace('_', ' ')}</h6>
                                                                <small className="text-muted">
                                                                    {new Date(log.timestamp).toLocaleString()}
                                                                </small>
                                                            </div>
                                                            <p className="mb-1 text-muted">{log.details}</p>
                                                            <small className="text-muted">Performed by: {log.performedBy} (Administrator)</small>
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            )}

            {/* --- FILTER MODAL --- */}
            {showFilterModal && (
                <div style={styles.modalOverlay} onClick={() => setShowFilterModal(false)}>
                    <div style={styles.modalContent} onClick={e => e.stopPropagation()}>
                        <div className="d-flex justify-content-between align-items-center p-4 bg-black text-white">
                            <h5 className="m-0 fw-bold">FILTER OPTIONS</h5>
                            <button className="btn btn-link text-white p-0" onClick={() => setShowFilterModal(false)}>×</button>
                        </div>
                        <div className="p-4">
                            <div className="mb-4">
                                <h6 className="fw-bold mb-3">Stock Status</h6>
                                <div className="form-check">
                                    <input className="form-check-input" type="radio" name="stockFilter" id="stockAll" value="all" checked={stockFilter === 'all'} onChange={(e) => setStockFilter(e.target.value)} />
                                    <label className="form-check-label" htmlFor="stockAll">All Items</label>
                                </div>
                                <div className="form-check">
                                    <input className="form-check-input" type="radio" name="stockFilter" id="stockLow" value="low" checked={stockFilter === 'low'} onChange={(e) => setStockFilter(e.target.value)} />
                                    <label className="form-check-label" htmlFor="stockLow">Low Stock (&lt; 10)</label>
                                </div>
                                <div className="form-check">
                                    <input className="form-check-input" type="radio" name="stockFilter" id="stockOk" value="ok" checked={stockFilter === 'ok'} onChange={(e) => setStockFilter(e.target.value)} />
                                    <label className="form-check-label" htmlFor="stockOk">In Stock (≥ 10)</label>
                                </div>
                            </div>
                            <div className="mb-4">
                                <h6 className="fw-bold mb-3">Categories</h6>
                                {uniqueCategories.map(category => (
                                    <div key={category} className="form-check">
                                        <input
                                            className="form-check-input"
                                            type="checkbox"
                                            id={`cat-${category}`}
                                            checked={selectedCategories.includes(category)}
                                            onChange={(e) => {
                                                if (e.target.checked) {
                                                    setSelectedCategories([...selectedCategories, category]);
                                                } else {
                                                    setSelectedCategories(selectedCategories.filter(c => c !== category));
                                                }
                                            }}
                                        />
                                        <label className="form-check-label" htmlFor={`cat-${category}`}>{category}</label>
                                    </div>
                                ))}
                            </div>
                            <div className="d-flex gap-2">
                                <button className="btn btn-dark rounded-0" onClick={() => { setSelectedCategories([]); setStockFilter('all'); setCurrentPage(1); }}>CLEAR ALL</button>
                                <button className="btn btn-outline-dark rounded-0 ms-auto" onClick={() => setShowFilterModal(false)}>APPLY</button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* --- 5. THE ANIMATION COMPONENT (Only visible when navigating) --- */}
            {isNavigating && (
                <div style={styles.loaderOverlay}>
                    <div className="wave-loader">
                        <div className="wave-dot"></div>
                        <div className="wave-dot"></div>
                        <div className="wave-dot"></div>
                        <div className="wave-dot"></div>
                        <div className="wave-dot"></div>
                    </div>
                    <div className="mt-4 text-dark small fw-bold text-uppercase" style={{ letterSpacing: '2px' }}>Processing Request</div>
                </div>
            )}
        </div>
    );
}

export default DisplayItem;